    with open('csv/superhero.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            hero_names[int(row['id'])] = row['superhero_name']
    print('Loaded superhero names from CSV')
else:
    import sqlite3
    conn = sqlite3.connect('db/superhero.db')
    cursor = conn.cursor()
    cursor.execute('SELECT id, superhero_name FROM superhero')
    for row in cursor.fetchall():
        hero_names[row[0]] = row[1]
    conn.close()
    print('Loaded superhero names from database')

